export function fovFor(n,e,t,r,o=!1){if(!(e>0)||e>=t&&!o||e===t)return n;const i=n*Math.PI/360,m=360/Math.PI*Math.atan(Math.tan(i)*(t/e));return Math.min(r,m)}export function poseFor(n,e,t){const r=t.stations[n]||t.stations.desk,o=[...r.eye];if(r.retreat&&e>0&&e<t.view.refAspect){const i=t.view.narrowAspect||.45,m=Math.min(1,(t.view.refAspect-e)/(t.view.refAspect-i)),s=r.eye.map((a,v)=>a-r.aim[v]),u=Math.hypot(...s)||1;for(let a=0;a<3;a++)o[a]+=s[a]/u*r.retreat*m}return{eye:o,aim:[...r.aim],fov:fovFor(r.fov,e,t.view.refAspect,r.maxFov||t.view.maxFov,!!r.holdWidth)}}export function smoothstep(n){const e=Math.min(1,Math.max(0,n));return e*e*(3-2*e)}const h=(n,e,t)=>n+(e-n)*t;export function blendPose(n,e,t){return{eye:n.eye.map((r,o)=>h(r,e.eye[o],t)),aim:n.aim.map((r,o)=>h(r,e.aim[o],t)),fov:h(n.fov,e.fov,t)}}export function createGlide(n,e,t){let r=0;return{to:e,step(o){r+=Math.max(0,o);const i=t>0?smoothstep(r/t):1;return blendPose(n,e,i)},get done(){return t<=0||r>=t}}}
